const bundle=read('dist/index.html').match(/<script type="module">([\s\S]*)<\/script>/)[1];
const strip=s=>s.replace(/^import .*?;\s*$/gm,'').replace(/\bexport\s+(?=(const|function)\b)/g,'');
const results=[];
async function test(ids,name,fn,environment='Node source/controller harness'){
  const t=performance.now();
  try{const detail=await fn();results.push({id:'AUTO-'+String(results.length+1).padStart(3,'0'),cases:ids.split(' '),name,status:'Pass',actual:detail||'All explicit assertions passed.',environment,ms:+(performance.now()-t).toFixed(2),at:new Date().toISOString()});}
  catch(e){results.push({id:'AUTO-'+String(results.length+1).padStart(3,'0'),cases:ids.split(' '),name,status:e.code==='ERR_ASSERTION'?'Fail':'Blocked',actual:e.message,expected:e.expected,observed:e.actual,environment,ms:+(performance.now()-t).toFixed(2),at:new Date().toISOString()});}
}
const copy=x=>JSON.parse(JSON.stringify(x));
function harness(html,initial=new Map()){
  const nodes=new Map(),store=initial,listeners={},timers=[],posts=[];
  const fault={get:false,set:false,remove:false,setKeys:new Set(),removeKeys:new Set()};
  function element(id=''){
    const attrs=new Map(),classes=new Set();let content='',value='';
    const el={id,style:{},dataset:{},hidden:false,disabled:false,checked:false,open:false,readOnly:false,
      parentElement:{setAttribute(){}},focus(){},select(){},scrollIntoView(){},click(){return this.onclick?.()},
      classList:{add:x=>classes.add(x),remove:x=>classes.delete(x),contains:x=>classes.has(x),toggle:(x,on)=>on?classes.add(x):classes.delete(x)},
      setAttribute(k,v){attrs.set(k,String(v));if(k==='id')this.id=v},getAttribute:k=>attrs.get(k),removeAttribute:k=>attrs.delete(k),
      append(){},replaceChildren(){},showModal(){this.open=true},close(){this.open=false},
      querySelector(){return element()},querySelectorAll(){return []},closest(){return element()},dispatchEvent(){}};
    Object.defineProperty(el,'innerHTML',{get:()=>content,set:v=>{content=v;parse(v)}});
    Object.defineProperty(el,'value',{get:()=>value,set:v=>value=String(v)});
    Object.defineProperty(el,'textContent',{get:()=>content,set:v=>content=String(v)});
    Object.defineProperty(el,'selectedOptions',{get:()=>[{textContent:value==='hi-IN'?'Hindi':value==='en-IN'?'English':'Short sentences'}]});return el;
  }
  function parse(markup){for(const m of markup.matchAll(/<([a-z][a-z0-9]*)\b[^>]*\bid="([^"]+)"[^>]*>/g)){const tag=m[0],id=m[2],el=nodes.get(id)||element(id);if(!nodes.has(id)){el.hidden=/\bhidden\b/.test(tag);el.disabled=/\bdisabled\b/.test(tag);el.checked=/\bchecked\b/.test(tag);el.value=tag.match(/\bvalue="([^"]*)"/)?.[1]||'';nodes.set(id,el)}}}
  parse(html);
  const document={getElementById:id=>nodes.get(id)||null,querySelectorAll:()=>[],querySelector:()=>null,createElement:()=>element(),createTextNode:()=>element(),createDocumentFragment:()=>element(),body:element()};
  const context={document,console,crypto:webcrypto,location:{hash:'',origin:'https://qa.example.test'},navigator:{locks:{request:(_name,task)=>task()}},URL,Blob,Event,
    localStorage:{getItem:k=>{if(fault.get)throw Error('Injected storage read failure');return store.get(k)||null},setItem:(k,v)=>{if(fault.set||fault.setKeys.has(k))throw Error('Injected quota failure');store.set(k,v)},removeItem:k=>{if(fault.remove||fault.removeKeys.has(k))throw Error('Injected remove failure');store.delete(k)}},
    setTimeout:(f,ms)=>{timers.push({f,ms,active:true});return timers.length},clearTimeout:i=>{if(timers[i-1])timers[i-1].active=false},setInterval:(f,ms)=>{timers.push({f,ms,interval:true,active:true});return timers.length},clearInterval:i=>{if(timers[i-1])timers[i-1].active=false},confirm:()=>true,
    performance,addEventListener:(n,f)=>(listeners[n]??=[]).push(f),removeEventListener(){},scrollTo(){},print(){}};
  context.window=context;context.parent={postMessage:(...a)=>posts.push(a)};vm.createContext(context);
  return {run:s=>vm.runInContext(s,context),nodes,store,context,fault,timers,posts,emit:(n,e)=>{for(const f of listeners[n]||[])f(e)},flush:ms=>{for(const t of [...timers])if(t.active&&!t.interval&&(ms===undefined||t.ms===ms)){t.active=false;t.f()}}};
}
const learner={id:'qa-l1',code:'QA-EN-01'};
const qs=makeBank('en-IN',1,'A');
function session(id='s1',scores=qs.map(()=>2),override={}){
  const bank=makeBank(override.lang||'en-IN',override.level||1,override.form||'A');
  return {id,learner:learner.id,lang:'en-IN',level:1,mode:'diagnostic',form:'A',at:'2026-09-12T10:00:00Z',responses:bank.map((q,i)=>{
    const score=scores[i]??null,answer=score===null?null:q.kind==='choice'?(score===0?(q.answer+1)%q.options.length:q.answer):score;
    return {item:q.id,domain:q.domain,score,supported:score===1,answer,response:score===null?'':q.kind==='choice'?q.options[answer]:'Observation'};
  }),...override};
}
const data=(sessions=[])=>({version:2,learners:[copy(learner)],sessions});
function app(d=data(),storage){const a=harness(read('src/index.html'),storage||new Map([[E.STORE_KEY,JSON.stringify(d)]]));a.run(bundle);return a;}
function reader(ctx){const r=harness(read('src/reader/index.html'));for(const [id,v] of [['language','en-IN'],['level','1'],['duration','60'],['seconds','60']])r.nodes.get(id).value=v;if(ctx)r.context.READING_CONTEXT=ctx;r.run(strip(read('src/reader/scoring.mjs'))+'\n'+strip(read('src/reader/app.js')));return r;}
function readingSession(id='rs1',override={}){return {id,learner:learner.id,lang:'en-IN',level:1,mode:'fluency',domain:'fluency',form:'reader',at:'2026-09-12T11:00:00Z',responses:[],seconds:30,passage:'Ria has a red ball.',transcript:'Ria has a blue ball.',words:[...tokens('Ria has a red ball.')].map((word,i)=>({word,state:i===3?'error':'correct'})),metrics:{correct:4,error:1,skipped:0,attempted:5,cwpm:8,accuracy:80},...override};}
const finish="while(run){const q=run.items[run.index];if(q.audio)run.heard.add(q.audio);run.chosen=q.kind==='choice'?q.answer:2;nextTask()}";

for(const lang of ['en-IN','hi-IN'])for(const level of [1,2,3])for(const form of ['A','B'])await test('CHK-01 CHK-02 CHK-03 CNT-01','Full content and controller run '+lang+'/'+level+'/'+form,()=>{
  const items=makeBank(lang,level,form);assert.equal(items.length,13);assert.equal(new Set(items.map(q=>q.id)).size,13);assert.deepEqual(DOMAINS.filter(d=>d.id!=='fluency').map(d=>items.filter(q=>q.domain===d.id).length),[2,2,2,2,3,1,1]);
  for(const q of items){assert.ok(q.prompt&&q.explanation);if(q.kind==='choice'){assert.equal(q.options.length,3);assert.ok(Number.isInteger(q.answer)&&q.answer>=0&&q.answer<3)}else assert.ok(q.rubric)}
  const a=app();a.run(`lang=${JSON.stringify(lang)};level=${level};startRun('${form==='B'?'recheck':'diagnostic'}');${finish}`);const s=JSON.parse(a.store.get(E.STORE_KEY)).sessions[0];assert.equal(s.responses.length,13);assert.ok(s.responses.every(r=>r.score===2));assert.equal(s.lang,lang);assert.equal(s.level,level);assert.equal(s.form,form);return '13 items; domain counts 2/2/2/2/3/1/1; keys in range; full controller completion saved 13 independent responses.';
});
await test('SCR-01 SCR-02 CHK-10','Score and support truth tables for every item',()=>{for(const q of [...qs,...makeBank('hi-IN',3,'B')]){assert.equal(E.questionScore(q,null),null);assert.equal(E.questionScore(q,undefined),null);if(q.kind==='observed')for(const n of [0,1,2])assert.equal(E.questionScore(q,n,true),n);else for(let a=0;a<3;a++)for(const help of [false,true])assert.equal(E.questionScore(q,a,help),a===q.answer?(help?1:2):0)}return '26 items × independent/supported/correct/wrong/null branches checked.'});
await test('SCR-03 SCR-04 REP-03','Latest scored evidence, practice exclusion and previous evidence',()=>{const base=session('base',qs.map(()=>0));const practice=session('p',qs.map(()=>2),{mode:'practice',at:'2026-09-12T12:00:00Z'});const recheck=session('b',qs.map(()=>2),{mode:'recheck',at:'2026-09-12T11:00:00Z',responses:session().responses.filter(r=>r.domain==='sounds')});const s=E.domainSummary(data([practice,recheck,base]),learner.id,'en-IN',1);assert.equal(s[0].latest.id,'b');assert.equal(s[0].previous.id,'base');assert.equal(s[1].latest.id,'base');assert.equal(s[1].ratio,0);return 'Unsorted baseline/recheck/practice: sounds latest=b, previous=base; decoding remains base, ratio 0.'});
await test('SCR-05 SCR-06','Priority ratios, stable domain ties and missing evidence',()=>{const s=E.domainSummary(data([session('tie',[2,0,2,0,2,2,2,2,2,2,2,2,null]),readingSession()]),learner.id,'en-IN',1);assert.deepEqual(E.priorities(s).map(d=>d.id),['sounds','decoding']);assert.equal(s.find(d=>d.id==='writing').ratio,null);return 'Equal sound/decoding ratios produce sounds then decoding. Missing writing and fluency excluded.'});
await test('SCR-07 NAV-06','Empty and perfect profiles do not manufacture deficits',()=>{assert.deepEqual(E.priorities(E.domainSummary(data(),learner.id,'en-IN',1)),[]);const s=E.domainSummary(data([session()]),learner.id,'en-IN',1);assert.deepEqual(E.priorities(s),[]);assert.match(E.interpretation(s).text,/do not establish mastery/)});
