await test('SCR-10','Equal timestamps must not change latest evidence after array reorder',()=>{const a=session('a',qs.map(()=>0)),b=session('b');const first=E.domainSummary(data([a,b]),learner.id,'en-IN',1)[0].latest.id;const second=E.domainSummary(data([b,a]),learner.id,'en-IN',1)[0].latest.id;assert.equal(first,second,'Latest result changes from '+first+' to '+second+' solely when backup array order is reversed.');});
