await test('CHK-04 CHK-05 CHK-06 AUD-01','Unanswered gate and skipped denominator',()=>{const a=app(data([session()]));a.run("startRun('diagnostic');nextTask();");assert.equal(a.run('run.index'),0);a.run('while(run)nextTask(true)');const s=a.run('data.sessions.at(-1)');assert.ok(s.responses.every(r=>r.score===null));assert.equal(a.run('summary()[0].latest.id'),'s1');return 'Unanswered Next stays at index 0; all 13 skips score null and preserve previous profile.'});
