await test('CHK-13 PRC-01 PRC-02 SCR-04','Practice feedback and profile separation',()=>{const a=app(data([session('base',qs.map(()=>0))]));a.run("startRun('practice','sounds')");assert.match(a.nodes.get('activityContent').innerHTML,/Try it together/);a.run('renderTask();run.chosen=2;nextTask()');assert.equal(a.run('run.index'),0);assert.equal(a.run('run.feedback'),true);assert.match(a.nodes.get('activityContent').innerHTML,/They did this one on their own/);a.run(finish);assert.equal(a.run('data.sessions.length'),2);assert.equal(a.run('summary()[0].ratio'),0)});
await test('PRC-03 PRC-04','Rechecks are B and repeat is flagged',()=>{const a=app();a.run("startRun('recheck','sounds');"+finish+";closeActivity();startRun('recheck','sounds')");assert.equal(a.run('run.form'),'B');assert.equal(a.run('run.repeated'),true);a.run(finish+";closeActivity();startRun('practice','sounds');"+finish);assert.doesNotMatch(a.nodes.get('activityContent').innerHTML,/Try a fresh check/,'Practice following an already-used B form still says Try a fresh check.');});
