await test('DAT-08','Simultaneous stale writers preserve both completions',async()=>{
  const shared=new Map([[E.STORE_KEY,JSON.stringify(data())]]),a=app(data(),shared),b=app(data(),shared);
  let tail=Promise.resolve();const locks={request:(_name,task)=>{tail=tail.then(task);return tail}};
  a.context.navigator.locks=locks;b.context.navigator.locks=locks;
  a.run("startRun('diagnostic','sounds')");b.run("startRun('diagnostic','writing')");
  assert.notEqual(a.run('run.id'),b.run('run.id'),'These must be independent activities, not two resumes of one draft.');
  a.run(finish);b.run(finish);for(let i=0;i<5;i++)await tail;
  const saved=JSON.parse(shared.get(E.STORE_KEY));assert.equal(saved.sessions.length,2,'Concurrent saves must retain both independent completions.');
  assert.ok(E.validateBackup(saved));return 'Two controllers started distinct activities before either queued save ran; both completions survived serialized writes without storage events.';
});
