await test('BKP-01 BKP-02 BKP-03','JSON round trip, idempotence and existing-ID precedence',()=>{const d=data([session(),readingSession()]);assert.ok(E.validateBackup(d));assert.deepEqual(E.mergeBackup(d,copy(d)),d);const inc=copy(d);Object.assign(inc.sessions[0].responses[0],{score:0,answer:0,supported:false});inc.learners.push({id:'l2',code:'QA2'});inc.sessions.push(session('new',undefined,{learner:'l2'}));const merged=E.mergeBackup(d,inc);assert.equal(merged.sessions.length,3);assert.equal(merged.sessions[0].responses[0].score,2);assert.deepEqual(JSON.parse(JSON.stringify(d)),d)});
