function recognitionReader(){const r=reader();let speech;class Recognition{constructor(){speech=this}start(){}stop(){}abort(){}}r.context.SpeechRecognition=Recognition;return {r,get speech(){return speech}};}
// The Speech constructor is captured during boot; create a separate explicitly instrumented instance.
function asr(){const r=harness(read('src/reader/index.html'));for(const [id,v] of [['language','en-IN'],['level','1'],['duration','60'],['seconds','60']])r.nodes.get(id).value=v;const instances=[];r.context.SpeechRecognition=class{constructor(){instances.push(this)}start(){}stop(){}abort(){}};r.context.navigator.mediaDevices={getUserMedia:async()=>({getTracks:()=>[{stop(){}}]})};r.context.MediaRecorder=class{state='inactive';mimeType='audio/webm';start(){this.state='recording'}stop(){this.state='inactive';this.onstop?.()}};r.run(strip(read('src/reader/scoring.mjs'))+'\n'+strip(read('src/reader/app.js')));return {r,instances};}
