for(const duration of [60,120,0])await test('MIC-05 MIC-06 MIC-07 PER-04','Simulated recorder lifecycle duration '+duration,async()=>{const r=reader();let clock=0,stops=0;r.context.performance={now:()=>clock};r.context.navigator.mediaDevices={getUserMedia:async()=>({getTracks:()=>[{stop:()=>stops++}]})};r.context.MediaRecorder=class{state='inactive';mimeType='audio/webm';start(){this.state='recording'}stop(){this.state='inactive';this.ondataavailable?.({data:new Blob(['synthetic bytes'])});this.onstop?.()}};r.nodes.get('duration').value=duration;await r.nodes.get('recordBtn').onclick();assert.equal(r.run('phase'),'recording');clock=(duration||20)*1000;r.run(duration?'tick()':'stop()');r.flush(600);assert.equal(r.run('phase'),'review');assert.equal(Number(r.nodes.get('seconds').value),duration||20);assert.ok(stops>0);assert.equal(r.nodes.get('downloadAudio').hidden,false);r.emit('pagehide',{});return 'Simulated stream, timer, recorder stop and download blob completed; no audible hardware claim.'});
await test('BKP-09','Multibyte oversized file and paste parity through import handlers',async()=>{const d=data(Array.from({length:6500},(_,i)=>session('big-'+i,[],{responses:[{...session().responses[0],note:'क'.repeat(500)}]})));assert.ok(E.validateBackup(d));const raw=JSON.stringify(d),bytes=Buffer.byteLength(raw);assert.ok(bytes>10*1024*1024&&raw.length<10*1024*1024);const a=app();await a.nodes.get('importFile').onchange({target:{files:[{size:bytes,text:async()=>raw}],value:'selected'}});assert.equal(a.run('data.sessions.length'),0);a.nodes.get('pastedBackup').value=raw;a.nodes.get('applyPastedBackup').onclick();assert.equal(a.run('data.sessions.length'),0,`${bytes} UTF-8 bytes / ${raw.length} UTF-16 units: file rejected but paste imported 6500 sessions.`)});
await test('BKP-05 BKP-10 BKP-12','Cancelled file, invalid JSON and failed clipboard preserve export',async()=>{const a=app(data([session()]));const prior=a.store.get(E.STORE_KEY);await a.nodes.get('importFile').onchange({target:{files:[],value:''}});a.nodes.get('pastedBackup').value='{not json';a.nodes.get('applyPastedBackup').onclick();assert.equal(a.store.get(E.STORE_KEY),prior);a.nodes.get('backupBtn').onclick();a.context.navigator.clipboard={writeText:async()=>{throw Error('denied')}};await a.nodes.get('copyExport').onclick();assert.match(a.nodes.get('exportNotice').textContent,/Select the text/);assert.equal(JSON.parse(a.nodes.get('exportText').value).sessions.length,1)});
