for(const [name,mutate] of [
  ['choice range',d=>d.chosen=99],['oversized current evidence',d=>d.evidence='x'.repeat(2001)],
  ['invented heard story',d=>d.heard=['not a curriculum story']],['wrong feedback mode',d=>d.feedback=true]
])await test('DRF-07','Reject invalid draft '+name,()=>{
  const a=app();a.run("startRun('diagnostic','sounds');closeActivity()");
  const draft=JSON.parse(a.store.get('language-studio-draft-v2'));mutate(draft);a.store.set('language-studio-draft-v2',JSON.stringify(draft));
  const b=app(data(),new Map(a.store));assert.equal(b.run('readDraft()'),null);
});
await test('DRF-07','A corrupt draft is preserved while a new activity can pause',()=>{
  const a=app();a.store.set('language-studio-draft-v2','{broken');a.run("startRun('diagnostic','sounds');run.chosen=2;closeActivity()");
  assert.equal(a.store.get('language-studio-draft-v2-recovery'),'{broken');assert.equal(a.run('readDraft().chosen'),2);assert.equal(a.run('hasUnsaved'),false);
});
await test('DAT-10','A completed stale draft does not block the next activity',()=>{
  const a=app();a.run("startRun('diagnostic','sounds');run.chosen=2;closeActivity()");const prior=a.store.get('language-studio-draft-v2');
  a.run('resumeRun();'+finish);a.store.set('language-studio-draft-v2',prior);a.run("closeActivity();startRun('diagnostic','writing');closeActivity()");
  assert.equal(a.run('readDraft().domain'),'writing');assert.equal(a.run('hasUnsaved'),false);
});
await test('DAT-08 LRN-03','Concurrent duplicate-code creation is rejected under the lock',async()=>{
  const shared=new Map([[E.STORE_KEY,JSON.stringify(data())]]),a=app(data(),shared),b=app(data(),shared);let tail=Promise.resolve();
  const locks={request:(_name,task)=>{tail=tail.then(task);return tail}};a.context.navigator.locks=locks;b.context.navigator.locks=locks;
  for(const instance of [a,b]){instance.nodes.get('learnerCode').value='NEW';instance.nodes.get('setupLanguage').value='en-IN';instance.nodes.get('setupLevel').value='1';instance.nodes.get('learnerForm').onsubmit({preventDefault(){}})}
  await tail;assert.equal(JSON.parse(shared.get(E.STORE_KEY)).learners.length,2);assert.match(b.nodes.get('learnerError').textContent,/conflict/i);
});
