for(const r of results){
  if(r.name==='Interpretation branches retain uncertainty')r.cases=['SCR-09'];
  if(r.status==='Fail'&&r.name==='Rechecks are B and repeat is flagged')r.cases=['PRC-04'];
  if(r.status==='Fail'&&r.name==='Draft quota warning survives an unrelated successful save')r.cases=['DAT-12'];
  if(r.status==='Fail'&&r.name==='Punctuation-only words excluded from meaningful scores')r.cases=['RDR-05'];
  if(r.status==='Fail'&&r.name==='Transcription off by default and unavailable option disabled')r.cases=['ASR-02'];
}
