console.log(JSON.stringify({checks:results.length,counts:results.reduce((a,r)=>(a[r.status]=(a[r.status]||0)+1,a),{}),failures:results.filter(r=>r.status!=='Pass').map(r=>({id:r.id,cases:r.cases,name:r.name,actual:r.actual}))},null,2));

